import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

const ALGORITHM = "aes-256-gcm";
const IV_LENGTH = 12;
const TAG_LENGTH = 16;
const HEADER_LENGTH = 1 + IV_LENGTH + TAG_LENGTH;

export interface KeyRing {
  activeVersion: number;
  keys: Map<number, Buffer>;
}

export class SaveDecryptError extends Error {
  constructor(message: string, readonly playerId: string) {
    super(message);
    this.name = "SaveDecryptError";
  }
}

function aadFor(playerId: string, slot: number): Buffer {
  return Buffer.from(`save:v1:${playerId}:${slot}`, "utf8");
}

export function sealSave(ring: KeyRing, playerId: string, slot: number, plaintext: Buffer): Buffer {
  const key = ring.keys.get(ring.activeVersion);
  if (!key || key.length !== 32) {
    throw new Error(`active key version ${ring.activeVersion} missing or wrong size`);
  }
  const iv = randomBytes(IV_LENGTH);
  const cipher = createCipheriv(ALGORITHM, key, iv, { authTagLength: TAG_LENGTH });
  cipher.setAAD(aadFor(playerId, slot));
  const body = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([Buffer.from([ring.activeVersion]), iv, tag, body]);
}

export function openSave(ring: KeyRing, playerId: string, slot: number, blob: Buffer): Buffer {
  if (blob.length < HEADER_LENGTH) {
    throw new SaveDecryptError("save blob truncated", playerId);
  }
  const version = blob.readUInt8(0);
  const key = ring.keys.get(version);
  if (!key) {
    throw new SaveDecryptError(`unknown key version ${version}`, playerId);
  }
  const iv = blob.subarray(1, 1 + IV_LENGTH);
  const tag = blob.subarray(1 + IV_LENGTH, HEADER_LENGTH);
  const body = blob.subarray(HEADER_LENGTH);
  const decipher = createDecipheriv(ALGORITHM, key, iv, { authTagLength: TAG_LENGTH });
  decipher.setAAD(aadFor(playerId, slot));
  decipher.setAuthTag(tag);
  try {
    return Buffer.concat([decipher.update(body), decipher.final()]);
  } catch {
    throw new SaveDecryptError("save failed authentication", playerId);
  }
}

export function needsRewrap(ring: KeyRing, blob: Buffer): boolean {
  return blob.length > 0 && blob.readUInt8(0) !== ring.activeVersion;
}

import { Pool } from "pg";
import { KeyRing, openSave, sealSave, needsRewrap, SaveDecryptError } from "./saveCrypto";

export interface GameSave {
  level: number;
  inventory: string[];
  coins: number;
  updatedAt: string;
}

export class SaveStore {
  constructor(private readonly db: Pool, private readonly ring: KeyRing) {}

  async write(playerId: string, slot: number, save: GameSave): Promise<void> {
    const blob = sealSave(this.ring, playerId, slot, Buffer.from(JSON.stringify(save), "utf8"));
    await this.db.query(
      `INSERT INTO player_saves (player_id, slot, blob, updated_at)
       VALUES ($1, $2, $3, now())
       ON CONFLICT (player_id, slot) DO UPDATE SET blob = EXCLUDED.blob, updated_at = now()`,
      [playerId, slot, blob],
    );
  }

  async read(playerId: string, slot: number): Promise<GameSave | null> {
    const res = await this.db.query<{ blob: Buffer }>(
      "SELECT blob FROM player_saves WHERE player_id = $1 AND slot = $2",
      [playerId, slot],
    );
    if (res.rowCount === 0) return null;
    const blob = res.rows[0].blob;
    let plaintext: Buffer;
    try {
      plaintext = openSave(this.ring, playerId, slot, blob);
    } catch (err) {
      if (err instanceof SaveDecryptError) {
        console.warn(JSON.stringify({ event: "save_decrypt_failed", playerId, slot, reason: err.message }));
      }
      throw err;
    }
    const save = JSON.parse(plaintext.toString("utf8")) as GameSave;
    if (needsRewrap(this.ring, blob)) {
      await this.write(playerId, slot, save);
    }
    return save;
  }
}

import { readFileSync } from "node:fs";
import { createServer } from "node:https";
import { Pool } from "pg";
import { SaveStore } from "./saveStore";
import { KeyRing } from "./saveCrypto";

function loadKeyRing(): KeyRing {
  const keys = new Map<number, Buffer>();
  for (const [name, value] of Object.entries(process.env)) {
    const match = /^SAVE_KEY_V(\d+)$/.exec(name);
    if (match && value) keys.set(Number(match[1]), Buffer.from(value, "base64"));
  }
  const activeVersion = Number(process.env.SAVE_KEY_ACTIVE);
  if (!keys.has(activeVersion)) throw new Error("SAVE_KEY_ACTIVE does not reference a loaded key");
  return { activeVersion, keys };
}

const db = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { ca: readFileSync(process.env.DB_CA_PATH ?? "/etc/ssl/rds-ca.pem"), rejectUnauthorized: true },
});
const store = new SaveStore(db, loadKeyRing());

createServer(
  {
    key: readFileSync(process.env.TLS_KEY_PATH!),
    cert: readFileSync(process.env.TLS_CERT_PATH!),
    minVersion: "TLSv1.2",
  },
  async (req, res) => {
    const match = /^\/saves\/(\d+)$/.exec(req.url ?? "");
    const playerId = req.headers["x-player-id"];
    if (!match || typeof playerId !== "string") {
      res.writeHead(404).end();
      return;
    }
    try {
      const save = await store.read(playerId, Number(match[1]));
      if (!save) return void res.writeHead(404).end();
      res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify(save));
    } catch {
      res.writeHead(500).end();
    }
  },
).listen(8443);
